-- DRAFT / NOT APPLIED. Owner authorized bridge code only; enrollment, switches and deployment remain separate.
-- Generated by real Supabase CLI2.121.0 as20261022002309, then ordered after the required future-stamped waiver.
-- Shared maintenance lock BEFORE every account/card/job lock. Rollback takes its exclusive counterpart.
begin;
do $$ begin
 if to_regprocedure('public.career_apply_message_card_approve_own(uuid,text)') is null
  or to_regprocedure('public.career_apply_cloud_waiver_left(uuid,text,timestamp with time zone)') is null
  or to_regprocedure('public.career_apply_extension_begin_agent_own(jsonb,text,text)') is null
  or to_regprocedure('public.career_apply_cloud_ask(uuid,uuid,jsonb)') is null
  or to_regprocedure('public.career_apply_agent_submit_enabled()') is null then
  raise exception 'card cloud bridge prerequisites missing'; end if;
end $$;

create or replace function public.career_apply_message_cloud_prepare_context(p_user uuid,p_resume text) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare account jsonb;r public.career_apply_cloud_resumes;
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if not career_message_approval_private.cloud_eligible(p_user,clock_timestamp()) then raise exception 'cloud card disabled'; end if;
 select value into account from public.career_watch_kv where user_id=p_user and key='career:account';
 if account is null or coalesce(account->>'paused','false')<>'false' then raise exception 'cloud account paused or missing'; end if;
 select * into r from public.career_apply_cloud_resumes where user_id=p_user and sha256=p_resume
  and privacy_epoch=coalesce((account->>'epoch')::bigint,0) and encode(sha256(bytes),'hex')=sha256;
 if r.user_id is null then raise exception 'cloud owned resume mismatch'; end if;
 return jsonb_build_object('account',jsonb_build_object('epoch',coalesce((account->>'epoch')::bigint,0),'version',coalesce((account->>'version')::bigint,0)),
  'resume',jsonb_build_object('filename',r.filename,'sha256',r.sha256,'b64',encode(r.bytes,'base64')));
end $$;
create or replace function public.career_apply_message_cloud_prepare_questions_as(p_user uuid,p_job_id text,p_questions jsonb) returns integer
language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if not career_message_approval_private.cloud_eligible(p_user,clock_timestamp()) then raise exception 'cloud card disabled'; end if;
 return public.career_apply_questions_put_for(p_user,p_job_id,p_questions);
end $$;

create or replace function public.career_apply_message_cloud_authorize(p_id uuid,p_lease uuid,p_hash text,p_source_digest text default null) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid;j public.career_apply_jobs;n timestamptz;fam text;o public.career_apply_cloud_optin;account jsonb;snapshot jsonb;
 reason text;went text[]:=array['driving','confirmed','submitted_unconfirmed','needs_user','unknown_outcome'];
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 select user_id into u from public.career_apply_jobs where id=p_id;
 if u is null then raise exception 'invalid apply claim'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into j from public.career_apply_jobs where id=p_id for update;n:=clock_timestamp();
 if j.state is distinct from'driving' or j.source is distinct from'cloud' or j.lease_token is distinct from p_lease
  or p_lease is null or j.payload_hash is distinct from p_hash or j.claimed_at is null
  or j.claimed_at<=n-interval'15 minutes' then raise exception 'invalid apply claim'; end if;
 if not public.career_apply_cloud_enabled() or not public.career_apply_agent_submit_enabled() then raise exception 'cloud switches off'; end if;
 reason:=career_message_approval_private.cloud_bound_refusal(j,n,true);
 if reason is not null then raise exception '%',reason; end if;
 if coalesce(p_source_digest,'')!~'^[0-9a-f]{64}$' then raise exception 'invalid source digest'; end if;
 snapshot:=public.career_apply_message_cloud_sources(u);
 if snapshot->>'digest' is distinct from p_source_digest then raise exception 'approved sources changed'; end if;
 if public.career_apply_current(u,j.payload) is distinct from true then raise exception 'stale cloud authority'; end if;
 fam:=public.career_apply_portal(j.url);
 if fam is null or fam not in('greenhouse','lever','ashby') then raise exception 'portal_not_cloud'; end if;
 -- The current job already spent its one waiver send. Count it once, not again as a prospective claim.
 if not public.career_apply_cloud_open(fam) and not exists(select 1 from public.career_apply_cloud_gate_waivers w
  where w.user_id=u and w.portal=fam and w.revoked_at is null and w.created_at<=j.claimed_at and w.expires_at>n
   and (select count(*) from public.career_apply_jobs x where x.user_id=u and x.source='cloud' and x.attempts>0
    and x.claimed_at>=w.created_at and public.career_apply_portal(x.url)=fam)<=w.max_sends) then raise exception 'gate_closed'; end if;
 select * into o from public.career_apply_cloud_optin where user_id=u;
 select value into account from public.career_watch_kv where user_id=u and key='career:account';
 if o.user_id is null or not o.enabled or o.privacy_epoch is distinct from coalesce((account->>'epoch')::bigint,0) then raise exception 'not_opted_in'; end if;
 if exists(select 1 from public.career_apply_cloud_pauses where until>n and ((scope='portal' and portal=fam) or(scope='person' and user_id=u))) then raise exception 'cloud paused'; end if;
 if (select count(*) from public.career_apply_jobs where user_id=u and id<>j.id and state=any(went) and claimed_at>n-interval'1 day')
  >=least(15,coalesce(o.daily,15),public.career_apply_daily_limit(u)) then raise exception 'daily_limit'; end if;
 if public.career_apply_company_key(j.company)<>'' and exists(select 1 from public.career_apply_jobs x where x.user_id=u and x.id<>j.id and x.state=any(went)
  and coalesce(x.claimed_at,x.created_at)>n-interval'30 days' and public.career_apply_company_key(x.company)=public.career_apply_company_key(j.company)) then raise exception 'company_cooldown'; end if;
 if not exists(select 1 from public.career_apply_cloud_resumes r where r.user_id=u and r.sha256=j.payload->>'resume_sha256'
  and r.privacy_epoch=(j.payload->>'privacy_epoch')::bigint and encode(sha256(r.bytes),'hex')=r.sha256) then raise exception 'cloud resume changed'; end if;
 return jsonb_build_object('authorized',true,'job_id',p_id,'lease_token',p_lease,'payload_hash',p_hash);
end $$;

create table if not exists career_message_approval_private.cloud_card_enrollments (
 user_id uuid primary key references public.profiles(id) on delete cascade,
 purpose text not null check(purpose='first-real-card-cloud'),
 created_at timestamptz not null default now(), expires_at timestamptz not null,
 revoked_at timestamptz, approval_ref text not null check(length(btrim(approval_ref)) between 1 and 1000),
 check(expires_at>created_at and expires_at<=created_at+interval'24 hours')
);
create unique index if not exists career_cloud_card_one_enrollment on career_message_approval_private.cloud_card_enrollments((true)) where revoked_at is null;
create table if not exists career_message_approval_private.cloud_bound_approvals (
 approval_id uuid primary key references public.career_apply_batch_approvals(id),
 user_id uuid not null references public.profiles(id) on delete cascade,
 card_id uuid not null,item_index integer not null check(item_index>=0),
 payload_hash text not null check(payload_hash~'^[0-9a-f]{64}$'),
 approved_at timestamptz not null, expires_at timestamptz not null,revoked_at timestamptz,
 check(expires_at>approved_at and expires_at<=approved_at+interval'24 hours'),unique(card_id,item_index)
);
create table if not exists career_message_approval_private.cloud_bound_jobs (
 job_row_id uuid primary key, approval_id uuid not null unique references career_message_approval_private.cloud_bound_approvals(approval_id),
 user_id uuid not null references public.profiles(id) on delete cascade,
 card_id uuid not null,item_index integer not null,unique(card_id,item_index)
);
create table if not exists career_message_approval_private.cloud_tap_receipts (
 card_id uuid primary key,user_id uuid not null references public.profiles(id) on delete cascade,
 card_hash text not null,receipt jsonb not null
);
alter table career_message_approval_private.cloud_card_enrollments enable row level security;
alter table career_message_approval_private.cloud_bound_approvals enable row level security;
alter table career_message_approval_private.cloud_bound_jobs enable row level security;
alter table career_message_approval_private.cloud_tap_receipts enable row level security;
revoke all on career_message_approval_private.cloud_card_enrollments,career_message_approval_private.cloud_bound_approvals,
 career_message_approval_private.cloud_bound_jobs,career_message_approval_private.cloud_tap_receipts from public,anon,authenticated,service_role;
grant select,insert,update,delete on career_message_approval_private.cloud_card_enrollments to service_role;

create or replace function career_message_approval_private.cloud_eligible(u uuid,n timestamptz) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from career_message_approval_private.test_users where user_id=u and enabled)
 or exists(select 1 from career_message_approval_private.cloud_card_enrollments
  where user_id=u and revoked_at is null and created_at<=n and expires_at>n and purpose='first-real-card-cloud')
$$;
create or replace function public.career_apply_message_cloud_enabled_own() returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
 select auth.uid() is not null and career_message_approval_private.cloud_eligible(auth.uid(),clock_timestamp())
$$;
drop policy if exists career_apply_message_cards_owner_read on public.career_apply_message_cards;
create policy career_apply_message_cards_owner_read on public.career_apply_message_cards for select to authenticated
 using ((select auth.uid())=user_id and case when payload->>'version'='2' and payload->>'execution_mode'='cloud'
  then (select public.career_apply_message_cloud_enabled_own()) else (select public.career_apply_message_card_test_enabled_own()) end);

-- One MVCC snapshot, matching Claude's reader: freshest valid profile within25 flow rows, answered questions only.
-- No facts are interpreted/projected here. Worker passes these exact objects into the existing engineInput contract.
create or replace function public.career_apply_message_cloud_sources(p_user uuid) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare v jsonb;
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if not exists(select 1 from public.profiles where id=p_user) then raise exception 'source owner missing'; end if;
 with recent as(select state,updated_at,thread_id from public.agent_flow_state where user_id=p_user order by updated_at desc,thread_id limit 25),
 profile as(select state#>'{career,stores,profile}' p from recent
  where jsonb_typeof(state#>'{career,stores,profile}')='object' and
   (jsonb_typeof(state#>'{career,stores,profile,basics}')='object' or jsonb_typeof(state#>'{career,stores,profile,facts}')='array')
  order by updated_at desc,thread_id limit 1),
 rows as(select coalesce(jsonb_agg(jsonb_build_object('id',id,'user_id',user_id,'key',key,'kind',kind,'answer',answer,'state',state)
  order by id),'[]'::jsonb) r from public.career_apply_questions where user_id=p_user and state='answered')
 select jsonb_build_object('profile',(select p from profile),'rows',r) into v from rows;
 return v||jsonb_build_object('user_id',p_user,'digest',encode(sha256(convert_to(public.career_apply_canonical(v||jsonb_build_object('user_id',p_user)),'UTF8')),'hex'));
end $$;

create or replace function public.career_apply_message_cloud_card_show_as(p_user uuid,p_thread uuid,p_items jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare cid uuid:=gen_random_uuid();stamp bigint;body jsonb;h text;mid bigint;
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if not career_message_approval_private.cloud_eligible(p_user,clock_timestamp()) then raise exception 'cloud card disabled'; end if;
 perform 1 from public.agent_threads where id=p_thread and user_id=p_user for update;
 if not found then raise exception 'cloud card thread is not yours'; end if;
 perform career_message_approval_private.cloud_validate(p_user,p_items);
 stamp:=floor(extract(epoch from clock_timestamp())*1000)::bigint;
 body:=jsonb_build_object('version',2,'kind','career-message-approval','execution_mode','cloud','card_id',cid,'user_id',p_user,
  'thread_id',p_thread,'issued_at',stamp,'expires_at',stamp+86400000,'items',p_items);
 if octet_length(body::text)>1048576 then raise exception 'cloud card too large'; end if;
 h:=encode(sha256(convert_to(public.career_apply_canonical(body),'UTF8')),'hex');
 insert into public.agent_messages(thread_id,role,content,meta) values(p_thread,'assistant',
  'Review the exact application answers, destination and resume fingerprint before approving.',
  jsonb_build_object('career',true,'intent','career_message_approval','career_approval_card_id',cid)) returning id into mid;
 insert into public.career_apply_message_cards(id,user_id,thread_id,message_id,payload,payload_hash,shown_at,expires_at)
  values(cid,p_user,p_thread,mid,body,h,to_timestamp(stamp/1000.0),to_timestamp(stamp/1000.0)+interval'24 hours');
 return jsonb_build_object('id',cid,'payload',body,'hash',h,'state','open','message_id',mid);
end $$;

create or replace function career_message_approval_private.cloud_tap(p_card uuid,p_hash text) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid();c public.career_apply_message_cards;it jsonb;p jsonb;h text;aid uuid;
 stamp timestamptz;deadline timestamptz;j public.career_apply_jobs;jobs jsonb:='[]';receipt jsonb;n integer:=0;
begin
 if u is null then raise exception 'not signed in'; end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 -- Receipt survives deletion/expiry/revocation and never remints a permission. Actor+Hc must still match.
 select r.receipt into receipt from career_message_approval_private.cloud_tap_receipts r where card_id=p_card and user_id=u and card_hash=p_hash;
 if found then return receipt; end if;
 select * into c from public.career_apply_message_cards where id=p_card and user_id=u for update;
 if c.id is null or not exists(select 1 from public.agent_threads where id=c.thread_id and user_id=u) then raise exception 'cloud card is not yours'; end if;
 if c.payload_hash is distinct from p_hash or p_hash is distinct from encode(sha256(convert_to(public.career_apply_canonical(c.payload),'UTF8')),'hex')
  or c.payload->>'version' is distinct from'2' or c.payload->>'execution_mode' is distinct from'cloud'
  or c.payload->>'user_id' is distinct from u::text or c.payload->>'card_id' is distinct from c.id::text
  or c.payload->>'thread_id' is distinct from c.thread_id::text then raise exception 'invalid cloud card hash or owner'; end if;
 if c.approved_at is not null then raise exception 'cloud card already answered'; end if;
 if not career_message_approval_private.cloud_eligible(u,clock_timestamp()) then raise exception 'cloud card disabled'; end if;
 if c.expires_at<=clock_timestamp() then raise exception 'cloud card expired'; end if;
 perform career_message_approval_private.cloud_validate(u,c.payload->'items');
 stamp:=clock_timestamp();
 if stamp>=c.expires_at then raise exception 'cloud card expired'; end if;
 for it in select value from jsonb_array_elements(c.payload->'items') loop
  p:=it->'payload';h:=it->>'hash';deadline:=least((p->>'expires_at')::timestamptz,stamp+interval'24 hours');
  if deadline<=clock_timestamp() then raise exception 'cloud permission expired'; end if;
  insert into public.career_apply_batch_approvals(user_id,job_id,batch_hash,entry,approved_at,used_at)
   values(u,p->>'job_id',h,p,stamp,stamp) returning id into aid;
  insert into career_message_approval_private.cloud_bound_approvals(approval_id,user_id,card_id,item_index,payload_hash,approved_at,expires_at)
   values(aid,u,c.id,n,h,stamp,deadline);
  -- The queue trigger binds this newly created immutable item before INSERT returns. P is passed unmodified.
  j:=public.career_apply_enqueue(p,h,h,least(15,coalesce((select daily from public.career_apply_cloud_optin where user_id=u),15),public.career_apply_daily_limit(u)));
  if not exists(select 1 from career_message_approval_private.cloud_bound_jobs b where job_row_id=j.id and approval_id=aid and user_id=u)
   then raise exception 'cloud item was not bound'; end if;
  jobs:=jobs||jsonb_build_object('id',j.id,'approval_id',aid,'payload_hash',h,'expires_at',deadline);n:=n+1;
 end loop;
 receipt:=jsonb_build_object('card_id',c.id,'card_hash',p_hash,'approved_count',n,'approved_at',stamp,
  'approval_expires_at',stamp+interval'24 hours','jobs',jobs);
 insert into career_message_approval_private.cloud_tap_receipts(card_id,user_id,card_hash,receipt) values(c.id,u,p_hash,receipt);
 -- Keep the preexisting extension table's exact24h constraint. The per-item effective deadline is in immutable
 -- metadata/receipt, independently min(P expiry,tap+24h); P and the extension constraint are never restamped.
 update public.career_apply_message_cards set approved_at=stamp,approval_expires_at=stamp+interval'24 hours' where id=c.id;
 return receipt;
end $$;

-- Return a reason for any absent, wrong-route, stripped, renewed, changed or withdrawn origin. Called on every cloud
-- candidate, even when no account is enrolled; legacy text cards/direct enqueue are never cloud authorization.
create or replace function career_message_approval_private.cloud_bound_refusal(j public.career_apply_jobs,n timestamptz,live boolean default true) returns text
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare b career_message_approval_private.cloud_bound_jobs;a career_message_approval_private.cloud_bound_approvals;p public.career_apply_batch_approvals;
begin
 select * into b from career_message_approval_private.cloud_bound_jobs where job_row_id=j.id;
 if b.job_row_id is null then return'not_card_approved'; end if;
 select * into a from career_message_approval_private.cloud_bound_approvals where approval_id=b.approval_id;
 select * into p from public.career_apply_batch_approvals where id=b.approval_id;
 if a.approval_id is null or p.id is null or b.user_id is distinct from j.user_id or a.user_id is distinct from j.user_id
  or p.user_id is distinct from j.user_id or b.card_id is distinct from a.card_id or b.item_index is distinct from a.item_index
  or p.job_id is distinct from j.job_id or p.entry is distinct from j.payload
  or a.payload_hash is distinct from j.payload_hash or p.batch_hash is distinct from j.payload_hash
  or j.payload_hash is distinct from j.approval_hash or p.used_at is null
  or j.payload->>'user_id' is distinct from j.user_id::text or j.payload->>'job_id' is distinct from j.job_id
  or j.payload->>'url' is distinct from j.url or j.payload->>'company' is distinct from j.company
  or j.agent_batch_hash is not null or j.payload_hash is distinct from encode(sha256(convert_to(public.career_apply_canonical(j.payload),'UTF8')),'hex')
 then return'not_card_approved'; end if;
 if live and (a.revoked_at is not null or p.revoked_at is not null or a.expires_at<=n
  or (p.entry->>'expires_at')::timestamptz<=n or not career_message_approval_private.cloud_eligible(j.user_id,n)) then return'cloud permission disabled or expired'; end if;
 return null;
end $$;

create or replace function career_message_approval_private.cloud_guard(oldrow public.career_apply_jobs,newrow public.career_apply_jobs,is_update boolean) returns public.career_apply_jobs
language plpgsql security definer set search_path=public,pg_temp as $$
declare a career_message_approval_private.cloud_bound_approvals;b career_message_approval_private.cloud_bound_jobs;reason text;
begin
 select * into b from career_message_approval_private.cloud_bound_jobs where job_row_id=newrow.id;
 if is_update then
  if b.job_row_id is null then raise exception 'cloud immutable binding missing'; end if;
  if row(newrow.id,newrow.user_id,newrow.job_id,newrow.url,newrow.company,newrow.payload,newrow.payload_hash,newrow.approval_hash,newrow.agent_batch_hash)
   is distinct from row(oldrow.id,oldrow.user_id,oldrow.job_id,oldrow.url,oldrow.company,oldrow.payload,oldrow.payload_hash,oldrow.approval_hash,oldrow.agent_batch_hash)
  then raise exception 'cloud immutable queue binding'; end if;
 else
  select * into a from career_message_approval_private.cloud_bound_approvals x where user_id=newrow.user_id and payload_hash=newrow.payload_hash
   and not exists(select 1 from career_message_approval_private.cloud_bound_jobs y where y.approval_id=x.approval_id) order by approved_at desc limit 1;
  if a.approval_id is null or newrow.state<>'queued' or newrow.attempts<>0 or newrow.source is not null then raise exception 'cloud immutable origin missing'; end if;
  insert into career_message_approval_private.cloud_bound_jobs(job_row_id,approval_id,user_id,card_id,item_index)
   values(newrow.id,a.approval_id,a.user_id,a.card_id,a.item_index);
 end if;
 reason:=career_message_approval_private.cloud_bound_refusal(newrow,clock_timestamp(),newrow.state in('queued','driving'));
 if reason is not null then raise exception 'cloud immutable boundary: %',reason; end if;
 if is_update and oldrow.state<>'driving' and newrow.state='driving' and newrow.source is distinct from'cloud' then raise exception 'cloud route required'; end if;
 return newrow;
end $$;

-- Closed JSON object classes; no wildcard nested parameters enter the cloud engine through this service boundary.
create or replace function career_message_approval_private.cloud_keys(v jsonb,allowed text[]) returns boolean
language sql immutable set search_path=public,pg_temp as $$
 select jsonb_typeof(v)='object' and not exists(select 1 from jsonb_object_keys(v) k where not(k=any(allowed)))
$$;
create or replace function career_message_approval_private.cloud_source_ok(v jsonb) returns boolean
language sql immutable set search_path=public,pg_temp as $$
 select career_message_approval_private.cloud_keys(v,array['table','key','value']) and v->>'table' in('answers','saved')
  and jsonb_typeof(v->'key')='string' and length(v->>'key')>0 and jsonb_typeof(v->'value')='string' and length(v->>'value')>0
$$;
create or replace function career_message_approval_private.cloud_quarantined(v jsonb) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $$
declare k text; x jsonb;
begin
 -- Same bank-ID rule as fact_quarantine.ts. Own-chat id:F-033 is not a bank factId.
 if btrim(coalesce(v->>'factId',''))~'^F-0*(2[7-9]|[3-6][0-9]|7[0-9])$'
  or coalesce(v->>'provenance','')~*'(owner-delegated|answer-all)' then return true; end if;
 foreach k in array array['derived_from','derivedFrom'] loop
  if v?k then
   if jsonb_typeof(v->k)<>'array' then return true; end if;
   for x in select value from jsonb_array_elements(v->k) loop
    if jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='' or btrim(x#>>'{}')~'^F-0*(2[7-9]|[3-6][0-9]|7[0-9])$' then return true; end if;
   end loop;
  end if;
 end loop;
 return false;
end $$;
create or replace function career_message_approval_private.cloud_validate(p_user uuid,p_items jsonb) returns void
language plpgsql set search_path=public,pg_temp as $$
declare it jsonb;p jsonb;r jsonb;f jsonb;s jsonb;a jsonb;seen text[]:='{}';
begin
 if jsonb_typeof(p_items) is distinct from'array' or jsonb_array_length(p_items) not between 1 and 100 then raise exception 'invalid cloud items'; end if;
 for it in select value from jsonb_array_elements(p_items) loop
  p:=it->'payload';r:=it->'readback';
  if not coalesce(career_message_approval_private.cloud_keys(it,array['payload','hash','readback']),false)
   or not coalesce(career_message_approval_private.cloud_keys(p,array['version','user_id','job_id','company','url','fields','destination','resume_sha256',
    'page_field_names','engine_approval','schema_hash','privacy_epoch','account_version','expires_at','quarantine_version','manifest_hash',
    'replay_sources','resume_tailored','resume_persona','approved_snapshot']),false)
   or p->'version' is distinct from'1'::jsonb or p->>'user_id' is distinct from p_user::text
   or length(coalesce(p->>'job_id','')) not between 3 and 300 or length(coalesce(p->>'company','')) not between 1 and 200
   or coalesce(p->>'url','')!~'^https://' or coalesce(p->>'destination','')!~'^https://'
   or octet_length(p::text)>131072 or jsonb_typeof(p->'fields') is distinct from'array'
   or jsonb_typeof(p->'page_field_names') is distinct from'array' or jsonb_typeof(p->'replay_sources') is distinct from'array'
   or coalesce(p->>'engine_approval','')!~'^[0-9a-f]{64}$' or coalesce(p->>'schema_hash','')!~'^[0-9a-f]{64}$'
   or coalesce(p->>'manifest_hash','')!~'^[0-9a-f]{64}$' or p->>'quarantine_version' is distinct from'd007-v1'
   or coalesce(p->>'resume_sha256','')!~'^[0-9a-f]{64}$'
   or it->>'hash' is distinct from encode(sha256(convert_to(public.career_apply_canonical(p),'UTF8')),'hex')
  then raise exception 'invalid or stale cloud payload'; end if;
  if p->>'job_id'=any(seen) then raise exception 'duplicate cloud posting'; end if;seen:=array_append(seen,p->>'job_id');
  if public.career_apply_current(p_user,p) is distinct from true then raise exception 'stale cloud authority'; end if;
  if not coalesce(career_message_approval_private.cloud_keys(r,array['answers','resume_name','resume_sha256','destination','blank','employer_fields']),false)
   or jsonb_typeof(r->'answers') is distinct from'array' or jsonb_typeof(r->'blank') is distinct from'array'
   or jsonb_typeof(r->'employer_fields') is distinct from'array' or r->'employer_fields' is distinct from p->'page_field_names'
   or exists(select 1 from jsonb_array_elements(r->'blank')x where jsonb_typeof(x) is distinct from'string')
   or exists(select 1 from jsonb_array_elements(p->'page_field_names')x where jsonb_typeof(x) is distinct from'string' or x#>>'{}'='')
   or (select count(*) from jsonb_array_elements(p->'page_field_names'))<>(select count(distinct x#>>'{}') from jsonb_array_elements(p->'page_field_names')x)
   or coalesce(r->>'resume_name','')=''
   or r->>'resume_sha256' is distinct from p->>'resume_sha256' or r->>'destination' is distinct from p->>'destination'
   or (select array_agg(x->>'name' order by x->>'name') from jsonb_array_elements(r->'answers')x)
     is distinct from(select array_agg(x->>'name' order by x->>'name') from jsonb_array_elements(p->'fields')x)
   or (select count(*) from jsonb_array_elements(p->'fields'))<>(select count(distinct x->>'name') from jsonb_array_elements(p->'fields')x)
  then raise exception 'cloud readback mismatch'; end if;
  for f in select value from jsonb_array_elements(p->'fields') loop
   if not coalesce(career_message_approval_private.cloud_keys(f,array['name','label','value','factId','provenance','confirmation_event_id','authorizes','source']),false)
    or jsonb_typeof(f->'name') is distinct from'string' or coalesce(f->>'name','')='' or jsonb_typeof(f->'label') is distinct from'string' or coalesce(f->>'label','')=''
    or jsonb_typeof(f->'factId') is distinct from'string' or coalesce(f->>'factId','')=''
    or jsonb_typeof(f->'value') is null or jsonb_typeof(f->'value') not in('string','object','number','boolean')
    or (f?'authorizes' and jsonb_typeof(f->'authorizes') is distinct from'boolean')
    or not coalesce(career_message_approval_private.cloud_source_ok(f->'source'),false)
    or jsonb_typeof(f->'confirmation_event_id') is distinct from'string' or coalesce(f->>'confirmation_event_id','')=''
    or jsonb_typeof(f->'provenance') is distinct from'string' or coalesce(f->>'provenance','')=''
    or career_message_approval_private.cloud_quarantined(f) then raise exception 'invalid or quarantined cloud field'; end if;
   if jsonb_typeof(f->'value')='object' and (
    not coalesce(career_message_approval_private.cloud_keys(f->'value',array['filename','sha256']),false)
    or f->'value'->>'filename' is distinct from r->>'resume_name'
    or f->'value'->>'sha256' is distinct from p->>'resume_sha256'
    or f->>'factId' is distinct from 'approved-local-resume:'||(p->>'resume_sha256')) then
    raise exception 'invalid cloud file answer'; end if;
   select value into a from jsonb_array_elements(r->'answers') where value->>'name'=f->>'name';
   if not coalesce(career_message_approval_private.cloud_keys(a,array['name','label','value','shown','factId','kind']),false)
    or a->'value' is distinct from f->'value' or a->>'label' is distinct from f->>'label'
    or a->>'factId' is distinct from f->>'factId' or jsonb_typeof(a->'shown') is distinct from'string' then raise exception 'cloud answer readback mismatch'; end if;
  end loop;
  for s in select value from jsonb_array_elements(p->'replay_sources') loop
   if not coalesce(career_message_approval_private.cloud_keys(s,array['table','key','value','factId','event','provenance','authorizes']),false)
    or not coalesce(career_message_approval_private.cloud_source_ok(jsonb_build_object('table',s->'table','key',s->'key','value',s->'value')),false)
    or jsonb_typeof(s->'factId') is distinct from'string' or coalesce(s->>'factId','')=''
    or jsonb_typeof(s->'event') is distinct from'string' or coalesce(s->>'event','')=''
    or jsonb_typeof(s->'provenance') is distinct from'string' or coalesce(s->>'provenance','')=''
    or (s?'authorizes' and jsonb_typeof(s->'authorizes') is distinct from'boolean')
    or career_message_approval_private.cloud_quarantined(s) then raise exception 'invalid or quarantined replay source'; end if;
  end loop;
  if p?'approved_snapshot' then
   s:=p->'approved_snapshot';
   if not coalesce(career_message_approval_private.cloud_keys(s,array['schema','original']),false)
    or jsonb_typeof(s->'schema') is distinct from'array' or s->'original' is distinct from(p-'approved_snapshot')
    or encode(sha256(convert_to(public.career_apply_canonical(s->'schema'),'UTF8')),'hex') is distinct from p->>'schema_hash'
   then raise exception 'cloud approved schema mismatch'; end if;
  end if;
  if not exists(select 1 from public.career_apply_cloud_resumes x where x.user_id=p_user and x.sha256=p->>'resume_sha256'
   and x.privacy_epoch=(p->>'privacy_epoch')::bigint and encode(sha256(x.bytes),'hex')=x.sha256 and x.filename=r->>'resume_name')
  then raise exception 'cloud owned resume mismatch'; end if;
 end loop;
end $$;

-- Existing entrypoints: additive dispatch, exact extension body and full live waiver/cap logic.
create or replace function career_message_approval_private.guard_queue() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare n jsonb:=to_jsonb(new); o jsonb; marker career_message_approval_private.bound_approvals;
 old_marker boolean:=false; h text; e jsonb; p jsonb; a jsonb; f jsonb; d text; want text;
 resume_hash text; resume_name text; active_check boolean; bound_id uuid;
begin
 -- Cloud dispatch only; the original extension body below is preserved byte-for-byte.
 if tg_op='UPDATE' then
  if exists(select 1 from career_message_approval_private.cloud_bound_jobs where job_row_id=old.id) then
   return career_message_approval_private.cloud_guard(old,new,true); end if;
 end if;
 if exists(select 1 from career_message_approval_private.cloud_bound_jobs where job_row_id=new.id)
  or exists(select 1 from career_message_approval_private.cloud_bound_approvals where user_id=new.user_id and payload_hash=new.payload_hash) then
  if tg_op='UPDATE' then return career_message_approval_private.cloud_guard(old,new,true);
  else return career_message_approval_private.cloud_guard(null,new,false); end if;
 end if;
 if tg_op='UPDATE' then
  o:=to_jsonb(old);
  select exists(select 1 from career_message_approval_private.bound_approvals b
   where b.user_id=old.user_id and b.batch_hash=o->>'agent_batch_hash') into old_marker;
  if old_marker and row(n->>'agent_batch_hash',new.user_id,new.job_id,new.url,new.company,new.payload,new.approval_hash,new.payload_hash)
    is distinct from row(o->>'agent_batch_hash',old.user_id,old.job_id,old.url,old.company,old.payload,old.approval_hash,old.payload_hash) then
   raise exception 'message approval boundary: queue binding is immutable'; end if;
 end if;
 h:=n->>'agent_batch_hash';
 select approval_id into bound_id from career_message_approval_private.bound_jobs where job_row_id=new.id;
 if bound_id is not null then
  select * into marker from career_message_approval_private.bound_approvals where approval_id=bound_id;
  if marker.user_id is distinct from new.user_id or marker.batch_hash is distinct from h then
   raise exception 'message approval boundary: queue binding is immutable'; end if;
 else
  select * into marker from career_message_approval_private.bound_approvals b
   where b.user_id=new.user_id and b.batch_hash=h order by b.approved_at desc limit 1;
 end if;
 if marker.approval_id is null then return new; end if;
 -- Terminal evidence remains recordable after permission expires. Entry/payload association above stays immutable.
 active_check:=tg_op='INSERT' or not old_marker or new.state in ('queued','driving');
 if active_check and (marker.expires_at<=clock_timestamp() or not exists(select 1 from
  career_message_approval_private.test_users where user_id=new.user_id and enabled)) then
  raise exception 'message approval boundary: TEST disabled or permission expired'; end if;
 select entry into e from public.career_apply_batch_approvals where id=marker.approval_id and user_id=new.user_id
  and job_id=marker.job_id and batch_hash=h and used_at is not null and (not active_check or revoked_at is null);
 if e is null or h is distinct from encode(sha256(convert_to(public.career_apply_canonical(e),'UTF8')),'hex') then
  raise exception 'message approval boundary: canonical approval missing or changed'; end if;
 p:=new.payload;
 if jsonb_typeof(p) is distinct from 'object' or p->'version' is distinct from '1'::jsonb
  or exists(select 1 from jsonb_object_keys(p) k where k not in
   ('manifest_hash','quarantine_version','version','source','user_id','job_id','company','url','family','fields',
    'resume_name','resume_sha256','privacy_epoch','account_version','expires_at')) then
  raise exception 'message approval boundary: unknown or malformed payload parameter'; end if;
 if new.job_id is distinct from marker.job_id or p->>'job_id' is distinct from marker.job_id
  or p->>'user_id' is distinct from new.user_id::text or p->>'source' is distinct from 'extension'
  or p->>'company' is distinct from e->>'company' or new.company is distinct from e->>'company'
  or p->>'url' is distinct from e->>'url' or new.url is distinct from e->>'url'
  or p->>'manifest_hash' is distinct from e->>'manifest_hash' or p->>'quarantine_version' is distinct from e->>'quarantine_version'
  or e->>'quarantine_version' is distinct from 'd007-v1'
  or jsonb_typeof(p->'fields') is distinct from 'array'
  or new.payload_hash is distinct from new.approval_hash
  or new.approval_hash is distinct from encode(sha256(convert_to(public.career_apply_canonical(p),'UTF8')),'hex') then
  raise exception 'message approval boundary: destination or payload identity changed'; end if;
 if (select array_agg(x->>'name' order by x->>'name') from jsonb_array_elements(p->'fields')x)
  is distinct from (select array_agg(x->>'name' order by x->>'name') from jsonb_array_elements(e->'answers')x) then
  raise exception 'message approval boundary: fields changed'; end if;
 for a in select value from jsonb_array_elements(e->'answers') loop
  select value into f from jsonb_array_elements(p->'fields') where value->>'name'=a->>'name';
  if jsonb_typeof(f) is distinct from 'object' or exists(select 1 from jsonb_object_keys(f) k where k not in
    ('name','label','value','source','factId','detail'))
   or exists(select 1 from unnest(array['name','label','value','source','factId','detail']) k where jsonb_typeof(f->k) is distinct from 'string')
   or f->>'source' is distinct from 'trainee' or f->>'label' is distinct from a->>'label'
   or f->>'factId' is distinct from a->>'factId' then
   raise exception 'message approval boundary: field provenance changed'; end if;
  d:=f->>'detail';
  if a->>'kind'='checkbox' then
   -- Native default-value boxes and explicit yes/no buttons only. An unchecked box alone cannot distinguish
   -- a deliberate No from an unanswered question. Custom raw values/ambiguous button mappings are unsupported.
   if lower(a->>'value') in ('true','yes','y','on','checked') and a->>'shown'='Yes (checked)' then
    if not ((f->>'value'='Yes (checked)' and d='checked=true;value=on') or
     (f->>'value'='Yes' and d='checked=true;value=on;pressed=yes')) then
     raise exception 'message approval boundary: checkbox readback changed or unsupported'; end if;
   elsif lower(a->>'value') in ('false','no','n','off','unchecked') and a->>'shown'='No (left unchecked)' then
    if f->>'value' is distinct from 'No' or d is distinct from 'checked=false;value=on;pressed=no' then
     raise exception 'message approval boundary: checkbox No is ambiguous'; end if;
   else raise exception 'message approval boundary: unsupported checkbox mapping'; end if;
  else
   if f->>'value' is distinct from a->>'shown' then raise exception 'message approval boundary: shown answer changed'; end if;
   case a->>'kind'
    when 'text' then if d<>'' or a->>'value' is distinct from a->>'shown' then
     raise exception 'message approval boundary: hidden text detail or unsupported text mapping'; end if;
    when 'select' then if d is distinct from 'value='||(a->>'value') then raise exception 'message approval boundary: select raw value changed'; end if;
    when 'choice' then
     -- Raw values must use the planner's canonical comma+space separator, in DOM option order. Raw values
     -- containing commas/checked= cannot be disambiguated by this wire format and are refused.
     if coalesce(a->>'value','')='' or a->>'value' like '%checked=%'
      or array_to_string(string_to_array(a->>'value',', '),', ') is distinct from a->>'value'
      or exists(select 1 from unnest(string_to_array(a->>'value',', '))x where x='' or x like '%,%') then
      raise exception 'message approval boundary: unsupported choice mapping'; end if;
     select string_agg('checked='||x,',' order by ord) into want from unnest(string_to_array(a->>'value',', ')) with ordinality v(x,ord);
     if d is distinct from want then raise exception 'message approval boundary: choice raw values changed'; end if;
    when 'file' then
     if d !~ ('^'||(a->>'file')||':[0-9]+:([A-Za-z0-9!#$&^_.+-]+/[A-Za-z0-9!#$&^_.+-]+)?$') then
      raise exception 'message approval boundary: attached bytes changed or malformed'; end if;
     if a->>'factId'='approved-local-resume:'||(a->>'file') then
      resume_hash:=a->>'file'; resume_name:=a->>'shown';
      if p->>'resume_sha256' is distinct from resume_hash or p->>'resume_name' is distinct from resume_name then
       raise exception 'message approval boundary: prepared resume changed'; end if;
     end if;
    else raise exception 'message approval boundary: unsupported listed/raw mapping';
   end case;
  end if;
 end loop;
 if resume_hash is null then raise exception 'message approval boundary: prepared resume missing'; end if;
 if bound_id is null then
  insert into career_message_approval_private.bound_jobs(job_row_id,user_id,approval_id)
   values(new.id,new.user_id,marker.approval_id);
 end if;
 return new;
end $$;

create or replace function public.career_apply_message_card_approve_own(p_card uuid,p_hash text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare u uuid := auth.uid(); c public.career_apply_message_cards; n integer; stamp timestamptz;
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 if exists(select 1 from public.career_apply_message_cards where id=p_card and user_id=u and payload->>'version'='2' and payload->>'execution_mode'='cloud')
  or exists(select 1 from career_message_approval_private.cloud_tap_receipts where card_id=p_card and user_id=u and card_hash=p_hash)
 then return career_message_approval_private.cloud_tap(p_card,p_hash); end if;
 if u is null then raise exception 'not signed in'; end if;
 if not public.career_apply_message_card_test_enabled_own() then raise exception 'message approvals are TEST-only'; end if;
 -- Serialize separate Messages cards for one account too; the underlying batch mint replaces earlier live rows.
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into c from public.career_apply_message_cards where id=p_card and user_id=u for update;
 if c.id is null or not exists(select 1 from public.agent_threads where id=c.thread_id and user_id=u) then
  raise exception 'message approval card is not yours'; end if;
 if c.approved_at is not null then raise exception 'message approval card already used'; end if;
 if c.expires_at<=clock_timestamp() then raise exception 'message approval card expired'; end if;
 if p_hash is distinct from c.payload_hash
  or c.payload_hash is distinct from encode(sha256(convert_to(public.career_apply_canonical(c.payload),'UTF8')),'hex')
  or c.payload->>'card_id' is distinct from c.id::text or c.payload->>'user_id' is distinct from u::text
  or c.payload->>'thread_id' is distinct from c.thread_id::text
  or c.payload->>'kind' is distinct from 'career-message-approval' or c.payload->>'version' is distinct from '1'
 then raise exception 'invalid or stale message approval card'; end if;
 perform career_message_approval_private.validate_items(c.payload->'items');
 -- Resolved at invocation after the WO-101 migration. No alternative enqueue or submission path is introduced.
 stamp := clock_timestamp();
 if stamp>=c.expires_at then raise exception 'message approval card expired'; end if;
 n := public.career_apply_batch_approve_own(c.payload->'items');
 -- The existing mint's default now() is the transaction start. Use the same actual tap stamp for its new rows and
 -- this receipt, so a long transaction cannot shorten the permission or make the card promise a later deadline.
 update public.career_apply_batch_approvals a set approved_at=stamp
  where a.user_id=u and a.revoked_at is null and a.used_at is null
   and exists(select 1 from jsonb_array_elements(c.payload->'items') it
    where a.job_id=it->'entry'->>'jobId' and a.batch_hash=it->>'hash');
 insert into career_message_approval_private.bound_approvals(approval_id,user_id,job_id,batch_hash,approved_at,expires_at)
  select a.id,a.user_id,a.job_id,a.batch_hash,stamp,stamp+interval '24 hours'
  from public.career_apply_batch_approvals a
  where a.user_id=u and a.revoked_at is null and a.used_at is null and a.approved_at=stamp
   and exists(select 1 from jsonb_array_elements(c.payload->'items') it
    where a.job_id=it->'entry'->>'jobId' and a.batch_hash=it->>'hash');
 update public.career_apply_message_cards set approved_at=stamp,approval_expires_at=stamp+interval '24 hours' where id=c.id;
 return jsonb_build_object('card_id',c.id,'card_hash',c.payload_hash,'approved_count',n,
  'approved_at',stamp,'approval_expires_at',stamp+interval '24 hours');
end $$;

create or replace function public.career_apply_message_card_read_own(p_card uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare u uuid := auth.uid(); c public.career_apply_message_cards;
begin
 if u is not null then
  select * into c from public.career_apply_message_cards where id=p_card and user_id=u and payload->>'version'='2' and payload->>'execution_mode'='cloud';
  if c.id is not null then
   if c.approved_at is null and not career_message_approval_private.cloud_eligible(u,clock_timestamp()) then raise exception 'cloud card disabled'; end if;
   return jsonb_build_object('id',c.id,'payload',c.payload,'hash',c.payload_hash,'state',case when c.approved_at is not null then 'approved' when c.expires_at<=clock_timestamp() then 'expired' else 'open' end);
  end if;
 end if;
 if u is null then raise exception 'not signed in'; end if;
 if not public.career_apply_message_card_test_enabled_own() then raise exception 'message approvals are TEST-only'; end if;
 select * into c from public.career_apply_message_cards where id=p_card and user_id=u;
 if c.id is null or not exists(select 1 from public.agent_threads where id=c.thread_id and user_id=u) then
  raise exception 'message approval card is not yours'; end if;
 return jsonb_build_object('id',c.id,'payload',c.payload,'hash',c.payload_hash,'state',
  case when c.approved_at is not null then 'approved' when c.expires_at<=clock_timestamp() then 'expired' else 'open' end);
end $$;

create or replace function public.career_apply_claim_own(p_limit integer, p_source text) returns setof public.career_apply_jobs
language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid(); n timestamptz:=clock_timestamp();
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 if u is null then raise exception 'not signed in'; end if;
 if p_source is null or p_source not in ('own_computer', 'extension') then raise exception 'invalid apply source'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 n:=clock_timestamp();
 update public.career_apply_jobs set state='unknown_outcome',
  reason='application outcome unknown: the drive stopped before recording it; not retried',
  evidence=evidence||jsonb_build_object('swept_at',n),updated_at=n
  where user_id=u and state='driving' and claimed_at<n-interval '15 minutes' and source is distinct from 'cloud';
 return query
 with picked as (select id from public.career_apply_jobs where user_id=u and state='queued' and source is null
  and not exists(select 1 from career_message_approval_private.cloud_bound_jobs b where b.job_row_id=career_apply_jobs.id)
  and public.career_apply_current(user_id,payload) and approval_hash=payload_hash and attempts=0
  order by created_at,id limit greatest(0,least(6,coalesce(p_limit,0))) for update skip locked)
 update public.career_apply_jobs j set state='driving',attempts=1,claimed_at=n,lease_token=gen_random_uuid(),updated_at=n,source=p_source
  from picked where j.id=picked.id returning j.*;
end $$;

create or replace function public.career_apply_extension_begin_own(p_payload jsonb, p_approval text)
returns jsonb language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare u uuid := auth.uid(); h text; j public.career_apply_jobs;
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 if exists(select 1 from career_message_approval_private.cloud_bound_jobs b join public.career_apply_jobs x on x.id=b.job_row_id
  where x.user_id=u and x.job_id=p_payload->>'job_id') then raise exception 'cloud card cannot start through extension'; end if;
 if u is null then raise exception 'not signed in'; end if;
 if p_payload is null or jsonb_typeof(p_payload) <> 'object' or p_payload->>'user_id' is distinct from u::text then raise exception 'not your application'; end if;
 if p_payload->>'source' is distinct from 'extension' or coalesce(p_payload->>'url', '') !~ '^https://' then raise exception 'invalid extension application'; end if;
 h := encode(sha256(convert_to(public.career_apply_canonical(p_payload), 'UTF8')), 'hex');
 if p_approval is null or p_approval is distinct from h then raise exception 'invalid or stale application approval'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text, 0));
 delete from public.career_apply_jobs where user_id = u and job_id = p_payload->>'job_id' and state = 'not_submitted'
  and evidence->>'reason' = 'stopped before the click';
 j := public.career_apply_enqueue(p_payload, h, h, public.career_apply_daily_limit(u));
 update public.career_apply_jobs set state = 'driving', source = 'extension', attempts = 1, claimed_at = clock_timestamp(), lease_token = gen_random_uuid(),
  updated_at = clock_timestamp() where id = j.id returning * into j;
 return jsonb_build_object('id', j.id, 'lease', j.lease_token, 'payload_hash', j.payload_hash);
end $$;

create or replace function public.career_apply_cloud_refusal(j public.career_apply_jobs, p_now timestamptz) returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare fam text := public.career_apply_portal(j.url); o public.career_apply_cloud_optin; a jsonb; went text[] :=
 array['driving', 'confirmed', 'submitted_unconfirmed', 'needs_user', 'unknown_outcome']; co text := public.career_apply_company_key(j.company);
begin
 if career_message_approval_private.cloud_bound_refusal(j,p_now,true) is not null then
  return coalesce(career_message_approval_private.cloud_bound_refusal(j,p_now,true),'not_card_approved'); end if;
 if not public.career_apply_cloud_enabled() or not public.career_apply_agent_submit_enabled() then return 'cloud_switches_off'; end if;
 if j.state <> 'queued' or j.attempts <> 0 or j.source is not null or j.approval_hash is distinct from j.payload_hash
  or coalesce(j.payload->>'engine_approval', '') !~ '^[0-9a-f]{64}$' then return 'not_approved'; end if;
 if public.career_apply_current(j.user_id, j.payload) is distinct from true then return 'stale'; end if;
 if fam is null or fam not in ('greenhouse', 'lever', 'ashby') then return 'portal_not_cloud'; end if;
 -- A form only the person can submit (prepared with --person-submits: its destination is their own Submit press) is
 -- never the cloud's: a server has no person at the window.
 if coalesce(j.payload->>'destination', '') !~ '^https://' then return 'person_submits'; end if;
 if not public.career_apply_cloud_open(fam) and public.career_apply_cloud_waiver_left(j.user_id, fam, p_now) <= 0 then return 'gate_closed'; end if;
 select * into o from public.career_apply_cloud_optin where user_id = j.user_id;
 select value into a from public.career_watch_kv where user_id = j.user_id and key = 'career:account';
 if o.user_id is null or not o.enabled or o.privacy_epoch is distinct from coalesce((a->>'epoch')::bigint, 0) then return 'not_opted_in'; end if;
 if exists (select from public.career_apply_cloud_pauses where scope = 'portal' and portal = fam and until > p_now) then
  return 'portal_paused'; end if;
 if exists (select from public.career_apply_cloud_pauses where scope = 'person' and user_id = j.user_id and until > p_now) then
  return 'person_paused'; end if;
 if (select count(*) from public.career_apply_jobs where user_id = j.user_id and state = any(went) and claimed_at > p_now - interval '1 day')
  >= least(15, coalesce(o.daily, 15), public.career_apply_daily_limit(j.user_id)) then return 'daily_limit'; end if;
 if co <> '' and exists (select from public.career_apply_jobs x where x.user_id = j.user_id and x.id <> j.id and x.state = any(went)
  and coalesce(x.claimed_at, x.created_at) > p_now - interval '30 days' and public.career_apply_company_key(x.company) = co) then
  return 'company_cooldown'; end if;
 return null;
end $$;

create or replace function public.career_apply_cloud_claim_at(p_limit integer, p_now timestamptz) returns setof public.career_apply_jobs
language plpgsql security definer set search_path = public, pg_temp as $$
declare c uuid; u uuid; ids uuid[] := '{}'; dead uuid[]; users uuid[]; fams text[]; wf text[]; j public.career_apply_jobs; got int := 0;
 lim int := greatest(0, least(6, coalesce(p_limit, 0)));
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 if p_now is null or not public.career_apply_cloud_enabled() or not public.career_apply_agent_submit_enabled() then return; end if;
 -- Cloud drives that stopped without a result, and the candidates: queued, approved, of a person who turned the cloud on,
 -- on a family whose gate is open and which is not paused; one person's oldest first, then the next person's (so no one
 -- fills every context). Nothing is locked yet.
 dead := array(select id from public.career_apply_jobs where source = 'cloud' and state = 'driving' and claimed_at < p_now - interval '15 minutes');
 fams := array(select f from unnest(array['greenhouse', 'lever', 'ashby']) f where public.career_apply_cloud_open(f)
  and not exists (select from public.career_apply_cloud_pauses where scope = 'portal' and portal = f and until > p_now));
 -- 20261024120000: a family whose gate is closed is still a candidate for a person holding a live waiver on it (D-010 as
 -- changed by the owner, 2026-10-21); the refusal below decides each job, the waiver's own count included.
 wf := array(select distinct w.portal from public.career_apply_cloud_gate_waivers w where w.revoked_at is null and w.expires_at > p_now
  and not exists (select from public.career_apply_cloud_pauses where scope = 'portal' and portal = w.portal and until > p_now));
 if lim > 0 and (cardinality(fams) > 0 or cardinality(wf) > 0) then
  ids := array(select x.id from (select q.id, q.created_at, row_number() over (partition by q.user_id order by q.created_at, q.id) rn
        from public.career_apply_jobs q join career_message_approval_private.cloud_bound_jobs b on b.job_row_id=q.id and b.user_id=q.user_id
        join public.career_apply_cloud_optin o on o.user_id = q.user_id and o.enabled
        where q.state = 'queued' and q.attempts = 0 and q.source is null and q.approval_hash = q.payload_hash
         and (public.career_apply_portal(q.url) = any(fams)
          or (public.career_apply_portal(q.url) = any(wf) and public.career_apply_cloud_waiver_left(q.user_id, public.career_apply_portal(q.url), p_now) > 0))) x
        order by x.rn, x.created_at, x.id limit lim * 4);
 end if;
 -- Each person's lock first, in user id order, the same order every time (the finish, the enqueue and the own claim also
 -- take the person's lock before any row), so two of them can never wait on each other in a circle.
 users := array(select distinct user_id from public.career_apply_jobs where id = any(dead || ids) order by user_id);
 foreach u in array users loop
  perform pg_advisory_xact_lock(hashtextextended(u::text, 0));
 end loop;
 p_now:=clock_timestamp();
 if not public.career_apply_cloud_enabled() or not public.career_apply_agent_submit_enabled() then return; end if;
 -- A cloud drive that stopped without a result is unknown, an error in the telemetry, and never re-driven.
 for j in update public.career_apply_jobs set state = 'unknown_outcome',
   reason = 'application outcome unknown: the drive stopped before recording it; not retried',
   evidence = evidence || jsonb_build_object('swept_at', p_now), updated_at = p_now
   where id = any(dead) and source = 'cloud' and state = 'driving' and claimed_at < p_now - interval '15 minutes' returning * loop
  perform public.career_apply_cloud_record(j, 'error', 'unknown_outcome', p_now);
 end loop;
 foreach c in array ids loop
  exit when got >= lim;
  select * into j from public.career_apply_jobs where id = c and state = 'queued' for update skip locked;
  continue when not found;
  continue when public.career_apply_cloud_refusal(j, p_now) is not null;
  update public.career_apply_jobs set state = 'driving', attempts = 1, claimed_at = p_now, lease_token = gen_random_uuid(),
   updated_at = p_now, source = 'cloud' where id = j.id returning * into j;
  got := got + 1;
  return next j;
 end loop;
end $$;
-- Existing Stop applying entrypoint: retain all unused legacy revocations, and also revoke consumed cloud
-- approvals. A cloud approval is consumed when queued, so used_at IS NULL alone would miss every new cloud job.
create or replace function public.career_apply_batch_revoke_own()
returns integer language plpgsql security definer set search_path = public, pg_temp as $$
declare u uuid := auth.uid(); n integer; cloud_count integer;
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 if u is null then raise exception 'not signed in'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 update public.career_apply_batch_approvals set revoked_at = clock_timestamp() where user_id = u and revoked_at is null and used_at is null;
 get diagnostics n = row_count;
 update public.career_apply_batch_approvals a set revoked_at=clock_timestamp()
  where a.user_id=u and a.revoked_at is null and a.used_at is not null and exists(
   select 1 from career_message_approval_private.cloud_bound_approvals b where b.approval_id=a.id and b.user_id=u);
 get diagnostics cloud_count=row_count;
 update career_message_approval_private.cloud_bound_approvals set revoked_at=clock_timestamp() where user_id=u and revoked_at is null;
 update public.career_apply_jobs j set state='not_submitted',reason='cloud approval revoked',
  evidence=j.evidence||jsonb_build_object('reason','cloud approval revoked','revoked_at',clock_timestamp()),updated_at=clock_timestamp()
  where j.user_id=u and j.state='queued' and exists(select 1 from career_message_approval_private.cloud_bound_jobs b
   where b.job_row_id=j.id and b.user_id=u);
 -- Driving jobs retain their lease/outcome recording path; before-effect authorization now refuses their revocation.
 return n+cloud_count;
end $$;


-- Owner's later explicit cloud-only15/day ruling supersedes the old25 default for CLOUD only.
-- No existing opt-in rows are rewritten; old25/50 rows are capped effectively at every cloud boundary.
alter table public.career_apply_cloud_optin alter column daily set default 15;
create or replace function public.career_apply_cloud_optin_as(p_user uuid, p_on boolean, p_terms text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare a jsonb; d int;
begin
 perform pg_advisory_xact_lock_shared(hashtextextended('career-card-cloud-bridge-maintenance-v1',0));
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_user is null or p_on is null then raise exception 'invalid cloud opt-in'; end if;
 if p_on then
  if p_terms is null or length(btrim(p_terms)) not between 1 and 1500 then raise exception 'invalid cloud opt-in'; end if;
  select value into a from public.career_watch_kv where user_id = p_user and key = 'career:account';
  if a is null then raise exception 'no_account'; end if;
  if coalesce(a->>'paused', 'false') <> 'false' then raise exception 'account_paused'; end if;
  d := least(15, public.career_apply_daily_limit(p_user));
  insert into public.career_apply_cloud_optin (user_id, enabled, terms, terms_sha256, daily, privacy_epoch, turned_on_at, updated_at)
  values (p_user, true, p_terms, encode(sha256(convert_to(p_terms, 'UTF8')), 'hex'), d, coalesce((a->>'epoch')::bigint, 0), now(), now())
  on conflict (user_id) do update set enabled = true, terms = excluded.terms, terms_sha256 = excluded.terms_sha256, daily = excluded.daily,
   privacy_epoch = excluded.privacy_epoch, turned_on_at = excluded.turned_on_at, updated_at = now();
  return jsonb_build_object('enabled', true, 'daily', d);
 end if;
 update public.career_apply_cloud_optin set enabled = false, turned_off_at = now(), updated_at = now() where user_id = p_user;
 delete from public.career_apply_cloud_resumes where user_id = p_user;
 return jsonb_build_object('enabled', false);
end $$;

create or replace function public.career_apply_cloud_optin_get(p_user uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
 select coalesce((select jsonb_build_object('enabled', enabled, 'daily', least(15,coalesce(daily,15),public.career_apply_daily_limit(p_user)), 'terms', terms, 'terms_sha256', terms_sha256) from public.career_apply_cloud_optin
  where user_id = p_user), jsonb_build_object('enabled', false,'daily',least(15,public.career_apply_daily_limit(p_user))))
$$;

