revoke all on function public.career_apply_message_cloud_sources(uuid) from public,anon,authenticated,service_role;
grant execute on function public.career_apply_message_cloud_sources(uuid) to service_role;
revoke all on function public.career_apply_message_cloud_card_show_as(uuid,uuid,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.career_apply_message_cloud_card_show_as(uuid,uuid,jsonb) to service_role;
revoke all on function public.career_apply_message_cloud_authorize(uuid,uuid,text,text) from public,anon,authenticated,service_role;
grant execute on function public.career_apply_message_cloud_authorize(uuid,uuid,text,text) to service_role;
revoke all on function public.career_apply_message_cloud_prepare_context(uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.career_apply_message_cloud_prepare_context(uuid,text) to service_role;
revoke all on function public.career_apply_message_cloud_prepare_questions_as(uuid,text,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.career_apply_message_cloud_prepare_questions_as(uuid,text,jsonb) to service_role;
revoke all on function career_message_approval_private.cloud_eligible(uuid,timestamptz) from public,anon,authenticated,service_role;
revoke all on function career_message_approval_private.cloud_keys(jsonb,text[]) from public,anon,authenticated,service_role;
revoke all on function career_message_approval_private.cloud_source_ok(jsonb) from public,anon,authenticated,service_role;
revoke all on function career_message_approval_private.cloud_quarantined(jsonb) from public,anon,authenticated,service_role;
revoke all on function career_message_approval_private.cloud_validate(uuid,jsonb) from public,anon,authenticated,service_role;
revoke all on function career_message_approval_private.cloud_tap(uuid,text) from public,anon,authenticated,service_role;
revoke all on function career_message_approval_private.cloud_bound_refusal(public.career_apply_jobs,timestamptz,boolean) from public,anon,authenticated,service_role;
revoke all on function career_message_approval_private.cloud_guard(public.career_apply_jobs,public.career_apply_jobs,boolean) from public,anon,authenticated,service_role;
revoke all on function public.career_apply_message_cloud_enabled_own() from public,anon,authenticated,service_role;
grant execute on function public.career_apply_message_cloud_enabled_own() to authenticated;
revoke all on function public.career_apply_cloud_refusal(public.career_apply_jobs,timestamptz),public.career_apply_cloud_claim_at(integer,timestamptz) from public,anon,authenticated,service_role;
revoke all on function public.career_apply_message_card_read_own(uuid),public.career_apply_message_card_approve_own(uuid,text),public.career_apply_claim_own(integer,text),public.career_apply_extension_begin_own(jsonb,text),career_message_approval_private.guard_queue() from public,anon,authenticated,service_role;
grant execute on function public.career_apply_message_card_read_own(uuid),public.career_apply_message_card_approve_own(uuid,text),public.career_apply_claim_own(integer,text),public.career_apply_extension_begin_own(jsonb,text) to authenticated;
revoke all on function public.career_apply_batch_revoke_own() from public,anon,authenticated,service_role;
grant execute on function public.career_apply_batch_revoke_own() to authenticated;

revoke all on function public.career_apply_cloud_optin_as(uuid,boolean,text),public.career_apply_cloud_optin_get(uuid) from public,anon,authenticated,service_role;
grant execute on function public.career_apply_cloud_optin_as(uuid,boolean,text),public.career_apply_cloud_optin_get(uuid) to service_role;

